// ═══════════════════════════════════════════════════════════
// QUERY HASHING & NORMALIZATION
// Ensures raw query text is NEVER stored — only SHA-256 hash
// ═══════════════════════════════════════════════════════════

const crypto = require('crypto');
const input = $input.first().json;

// If query_hash wasn't pre-computed, compute it now
let queryHash = input.query_hash;
if (!queryHash && input.query) {
  // Normalize: lowercase, trim, collapse whitespace
  const normalized = (input.query || '').toLowerCase().trim().replace(/\s+/g, ' ');
  queryHash = crypto.createHash('sha256').update(normalized).digest('hex');
}

// Validate category
const validCategories = ['ACADEMIC', 'ADMINISTRATIVE', 'REJECTED', 'UNANSWERED', 'OFF_TOPIC', 'INAPPROPRIATE', 'ERROR'];
const category = validCategories.includes(input.category) ? input.category : 'UNANSWERED';

// Clamp match_score to 0-1 range
const matchScore = Math.max(0, Math.min(1, parseFloat(input.match_score) || 0));

// Ensure response_ms is non-negative
const responseMs = Math.max(0, parseInt(input.response_ms) || 0);

// docs_matched as PostgreSQL array format
const docsMatched = Array.isArray(input.docs_matched) ? input.docs_matched : [];

return [{
  json: {
    query_hash: queryHash,
    category: category,
    match_score: matchScore.toFixed(3),
    response_ms: responseMs,
    docs_matched: docsMatched,
    was_answered: input.was_answered === true,
    session_id: input.session_id || '00000000-0000-0000-0000-000000000000',
    rejection_layer: input.rejection_layer || null,
    created_at: input.created_at || new Date().toISOString()
  }
}];

// Split docs_matched array into individual items for upsert
const docs = $('Normalize & Hash').first().json.docs_matched || [];
return docs.map(doc => ({
  json: { document_name: doc }
}));

// Log completion (no output needed — this is async fire-and-forget)
const insertResult = $('Insert into query_logs').first().json;
console.log(`Analytics logged: ID=${insertResult?.id || 'unknown'}`);
return [{ json: { status: 'logged', id: insertResult?.id } }];
